package com.worklink.service;
import com.worklink.dto.proposal.*;import com.worklink.entity.*;import com.worklink.entity.enums.*;import com.worklink.exception.*;import com.worklink.repository.*;import com.worklink.security.CurrentUserProvider;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ProposalService {final ProposalRepository proposals;final ProjectRepository projects;final FreelancerProfileRepository freelancers;final ClientProfileRepository clients;final CurrentUserProvider current;
 public ProposalService(ProposalRepository a,ProjectRepository b,FreelancerProfileRepository c,ClientProfileRepository d,CurrentUserProvider e){proposals=a;projects=b;freelancers=c;clients=d;current=e;}
 FreelancerProfile me(){return freelancers.findByUserId(current.requireCurrentUser().id()).orElseThrow(ProfileNotFoundException::new);} ClientProfile client(){return clients.findByUserId(current.requireCurrentUser().id()).orElseThrow(ProfileNotFoundException::new);}
 @Transactional public ProposalResponse create(Long projectId,ProposalRequest r){Project p=projects.findById(projectId).orElseThrow(()->new ResourceNotFoundException("Project not found"));FreelancerProfile f=me();if(p.getStatus()!=ProjectStatus.PUBLISHED)throw new IllegalArgumentException("Only published projects can receive proposals");if(p.getClient().getUser().getId().equals(f.getUser().getId()))throw new IllegalArgumentException("You cannot propose to your own project");if(proposals.existsByProjectIdAndFreelancerId(projectId,f.getId()))throw new DuplicateResourceException("A proposal already exists for this project");return map(proposals.save(new Proposal(p,f,r.coverLetter().trim(),r.proposedBudget(),r.estimatedDuration(),ProposalStatus.SUBMITTED)));}
 @Transactional(readOnly=true) public List<ProposalResponse> mine(){return proposals.findByFreelancerId(me().getId()).stream().map(this::map).toList();}@Transactional(readOnly=true) public ProposalResponse mine(Long id){Proposal p=proposals.findById(id).filter(x->x.getFreelancer().getId().equals(me().getId())).orElseThrow(()->new ResourceNotFoundException("Proposal not found"));return map(p);}
 @Transactional public ProposalResponse withdraw(Long id){Proposal p=proposals.findById(id).filter(x->x.getFreelancer().getId().equals(me().getId())).orElseThrow(()->new ResourceNotFoundException("Proposal not found"));if(p.getStatus()==ProposalStatus.ACCEPTED||p.getStatus()==ProposalStatus.REJECTED)throw new IllegalArgumentException("This proposal cannot be withdrawn");p.setStatus(ProposalStatus.WITHDRAWN);return map(proposals.save(p));}
 Project owned(Long projectId){return projects.findByIdAndClientId(projectId,client().getId()).orElseThrow(()->new ResourceNotFoundException("Project not found"));}@Transactional(readOnly=true) public List<ProposalResponse> project(Long id){owned(id);return proposals.findByProjectId(id).stream().map(this::map).toList();}@Transactional(readOnly=true) public ProposalResponse project(Long projectId,Long id){owned(projectId);Proposal p=proposals.findById(id).filter(x->x.getProject().getId().equals(projectId)).orElseThrow(()->new ResourceNotFoundException("Proposal not found"));return map(p);}@Transactional public ProposalResponse status(Long projectId,Long id,ProposalStatusRequest r){owned(projectId);Proposal p=proposals.findById(id).filter(x->x.getProject().getId().equals(projectId)).orElseThrow(()->new ResourceNotFoundException("Proposal not found"));if(r.status()==ProposalStatus.SUBMITTED||r.status()==ProposalStatus.WITHDRAWN)throw new IllegalArgumentException("Invalid client proposal status");p.setStatus(r.status());return map(proposals.save(p));}
 ProposalResponse map(Proposal p){User u=p.getFreelancer().getUser();return new ProposalResponse(p.getId(),p.getProject().getId(),p.getProject().getTitle(),p.getFreelancer().getId(),u.getFirstName()+" "+u.getLastName(),p.getCoverLetter(),p.getProposedAmount(),p.getEstimatedDays(),p.getStatus().name(),p.getCreatedAt(),p.getUpdatedAt());}}
